output_text:
[
  {
    "id": "take_entrance_cart",
    "text": "The shopper is obliged to take the cart stationed at the entrance before completing the trip.",
    "abstraction": {
      "state_properties": {
        "entry_cart_station": "at(1,5)",
        "entry_cart_available": {
          "and": [
            "entry_cart_station",
            "cartAt(1,5)"
          ]
        },
        "has_cart": "hasCart"
      },
      "events": {
        "take_entrance_cart": {
          "pre": {
            "and": [
              "entry_cart_available",
              "PICKUP_CART"
            ]
          },
          "post": "has_cart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_entrance_cart"
    }
  },
  {
    "id": "cart_required_for_item_pickup",
    "text": "Products may only be picked up when the shopper currently has a cart.",
    "abstraction": {
      "state_properties": {
        "has_cart": "hasCart",
        "cartless": {
          "not": "has_cart"
        }
      },
      "events": {
        "item_pickup_without_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "cartless"
            ]
          },
          "post": null
        },
        "item_pickup_into_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "has_cart"
            ]
          },
          "post": "has_cart"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "item_pickup_without_cart"
    }
  },
  {
    "id": "no_hand_carrying",
    "text": "The shopper is prohibited from carrying loose goods by hand instead of placing them in the cart.",
    "abstraction": {
      "state_properties": {
        "has_cart": "hasCart",
        "carrying_by_hand": "handFull",
        "cartless": {
          "not": "has_cart"
        }
      },
      "events": {
        "hand_load_item": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "cartless"
            ]
          },
          "post": "carrying_by_hand"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "carrying_by_hand",
          "hand_load_item"
        ]
      }
    }
  },
  {
    "id": "return_cart_to_bay",
    "text": "Before leaving the store, the shopper must return the cart by leaving it in the return bay at cell (0,1).",
    "abstraction": {
      "state_properties": {
        "cart_return_bay": "at(0,1)",
        "has_cart": "hasCart",
        "cart_parked_in_return_bay": "cartAt(0,1)",
        "at_return_bay_with_cart": {
          "and": [
            "cart_return_bay",
            "has_cart"
          ]
        }
      },
      "events": {
        "return_cart": {
          "pre": {
            "and": [
              "at_return_bay_with_cart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_in_return_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "return_cart"
    }
  },
  {
    "id": "no_exit_before_cart_returned",
    "text": "The shopper is prohibited from exiting while still holding the cart or before the cart is parked in the return bay.",
    "abstraction": {
      "state_properties": {
        "has_cart": "hasCart",
        "cart_parked_in_return_bay": "cartAt(0,1)",
        "cart_not_returned": {
          "or": [
            "has_cart",
            {
              "not": "cart_parked_in_return_bay"
            }
          ]
        }
      },
      "events": {
        "exit_before_cart_returned": {
          "pre": {
            "and": [
              "EXIT",
              "cart_not_returned"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "exit_before_cart_returned"
    }
  },
  {
    "id": "no_cart_in_checkout_side",
    "text": "Carts are prohibited on the checkout side of the store, so the shopper must enter that area only after abandoning the cart.",
    "abstraction": {
      "state_properties": {
        "has_cart": "hasCart",
        "checkout_side": {
          "or": [
            "at(6,2)",
            "at(7,2)",
            "at(8,2)",
            "at(9,2)",
            "at(7,3)",
            "at(8,3)",
            "at(9,3)",
            "at(7,4)",
            "at(8,4)",
            "at(9,4)",
            "at(8,5)",
            "at(9,5)"
          ]
        },
        "cart_in_checkout_side": {
          "and": [
            "has_cart",
            "checkout_side"
          ]
        }
      },
      "events": {
        "move_cart_into_checkout_side": {
          "pre": {
            "and": [
              "MOVE",
              "has_cart"
            ]
          },
          "post": {
            "and": [
              "checkout_side",
              "has_cart"
            ]
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "cart_in_checkout_side",
          "move_cart_into_checkout_side"
        ]
      }
    }
  },
  {
    "id": "reclaim_temporarily_dropped_cart",
    "text": "If the cart is put down anywhere other than the return bay, the shopper is obliged to pick it back up before exiting.",
    "abstraction": {
      "state_properties": {
        "has_cart": "hasCart",
        "cart_return_bay": "at(0,1)",
        "not_return_bay": {
          "not": "cart_return_bay"
        }
      },
      "events": {
        "temporary_cart_drop": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "has_cart",
              "not_return_bay"
            ]
          },
          "post": {
            "not": "has_cart"
          }
        },
        "recover_cart": {
          "pre": "PICKUP_CART",
          "post": "has_cart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "temporary_cart_drop",
      "discharge": "recover_cart"
    }
  },
  {
    "id": "service_egg_cell_if_entered",
    "text": "The cell at (6,4) is a special product-service location: if the shopper enters it, they must perform a product pickup there rather than merely passing through.",
    "abstraction": {
      "state_properties": {
        "egg_service_cell": "at(6,4)",
        "has_cart": "hasCart"
      },
      "events": {
        "enter_egg_service_cell": {
          "pre": {
            "and": [
              "MOVE",
              {
                "not": "egg_service_cell"
              }
            ]
          },
          "post": "egg_service_cell"
        },
        "service_egg_cell": {
          "pre": {
            "and": [
              "egg_service_cell",
              "has_cart",
              "PICKUP_ITEM"
            ]
          },
          "post": "has_cart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "enter_egg_service_cell",
      "discharge": "service_egg_cell"
    }
  }
]
